const OG_ITEMS = [
  { file: 'default.png', title: 'Portal Pertanian Resmi' },
  { file: 'jurnal.png', title: 'Jurnal Tani & Riset Lapangan' },
  { file: 'topik-proteksi-tanaman.png', title: 'Proteksi Tanaman' },
  { file: 'topik-tanah-nutrisi.png', title: 'Tanah & Nutrisi' },
  { file: 'topik-budidaya.png', title: 'Budidaya' },
  { file: 'topik-air-irigasi.png', title: 'Air & Irigasi' },
  { file: 'topik-pascapanen-agribisnis.png', title: 'Pascapanen & Agribisnis' },
  { file: 'topik-sains-tanaman.png', title: 'Sains Tanaman' },
  { file: 'komoditas.png', title: 'Arsip Komoditas Tani' },
  { file: 'alat-diagnosa-gejala.png', title: 'Diagnosa Gejala Tanaman' },
  { file: 'alat-kalender-tanam.png', title: 'Kalender Tanam & Fase HST' },
  { file: 'alat-cuaca-tani.png', title: 'Cuaca Tani & Jendela Semprot' },
  { file: 'alat-kalkulator-dosis.png', title: 'Kalkulator Dosis Tangki 16L' },
  { file: 'produk.png', title: 'Katalog Produk Unggulan' },
];

function escapeXml(unsafe) {
  return unsafe.replace(/[<>&'"]/g, (c) => {
    switch (c) {
      case '<': return '&lt;';
      case '>': return '&gt;';
      case '&': return '&amp;';
      case '\'': return '&apos;';
      case '"': return '&quot;';
    }
  });
}

function buildSvg(title) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630">
  <defs>
    <linearGradient id="bg" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#1A6335" />
      <stop offset="100%" stop-color="#14522B" />
    </linearGradient>
  </defs>
  <!-- Background -->
  <rect width="1200" height="630" fill="url(#bg)" />

  <!-- Subtle corner aesthetic mark -->
  <circle cx="1180" cy="20" r="320" fill="#FFFFFF" fill-opacity="0.03" />

  <!-- Agritani Official Reverse Logo -->
  <g transform="translate(100, 95) scale(1.4)">
    ${LOGO_INNER}
  </g>

  <!-- Title (No uppercase label above) -->
  <text x="100" y="340" font-family="'Plus Jakarta Sans', 'Liberation Sans', 'DejaVu Sans', sans-serif" font-size="56" font-weight="700" fill="#FFFFFF" letter-spacing="-0.02em">
    ${escapeXml(title)}
  </text>

  <!-- Divider Line -->
  <line x1="100" y1="485" x2="1100" y2="485" stroke="#FFFFFF" stroke-opacity="0.2" stroke-width="1.5" />

  <!-- Mandatory Footer Baseline Text per DEC-016 & T-32 -->
  <text x="100" y="538" font-family="'Plus Jakarta Sans', 'Liberation Sans', 'DejaVu Sans', sans-serif" font-size="24" font-weight="400" fill="#FFFFFF" fill-opacity="0.85">
    agritani.com · Portal pertanian dikelola Arif Prabowo
  </text>
</svg>`;
}

async function run() {
  if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  }

  console.log(`Generating ${OG_ITEMS.length} OG images in ${OUTPUT_DIR}...`);

  for (const item of OG_ITEMS) {
    const svg = buildSvg(item.title);
    const dest = path.join(OUTPUT_DIR, item.file);

    await sharp(Buffer.from(svg))
      .png({ quality: 90, compressionLevel: 9 })
      .toFile(dest);

    const stat = fs.statSync(dest);
    const sizeKb = (stat.size / 1024).toFixed(1);
    console.log(`✓ Generated ${item.file} (${sizeKb} KB)`);
  }

  console.log('All OG images generated successfully.');
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});
